# -*- coding: cp1251 -*-"""ЛБ №2: Проектування та реалізація об'єктно-орієнтованих систем в Pythonз використанням класів і спадковості.Запуск:  python lab2.pyЗалежності: лише стандартна бібліотека (math, abc)."""import mathfrom abc import ABC, abstractmethod# ============================================================# ЗАВДАННЯ 1. Класова ієрархія з наслідуванням та поліморфізмом# Предметна область: транспортні засоби# ============================================================class Vehicle:    """Базовий клас транспортного засобу."""    def __init__(self, brand: str, max_speed: int):        self.brand = brand              # атрибут екземпляра        self.max_speed = max_speed      # атрибут екземпляра        self._wheels = 0                # захищений, заповнюється підкласами    def move(self) -> str:        """Метод, що перевизначається підкласами (поліморфізм)."""        return f"{self.brand} рухається зі швидкістю до {self.max_speed} км/год"    def __str__(self) -> str:        return f"{type(self).__name__}(brand={self.brand}, max_speed={self.max_speed})"    def __repr__(self) -> str:        return f"{type(self).__name__}({self.brand!r}, {self.max_speed!r})"class Car(Vehicle):    def __init__(self, brand, max_speed, doors):        super().__init__(brand, max_speed)        self.doors = doors        self._wheels = 4    def move(self) -> str:        return f"Автомобіль {self.brand} їде по дорозі ({self.doors} дверей, {self._wheels} колеса)"class Bicycle(Vehicle):    def __init__(self, brand, max_speed, gears):        super().__init__(brand, max_speed)        self.gears = gears        self._wheels = 2    def move(self) -> str:        return f"Велосипед {self.brand} котиться з {self.gears} передачами"class Airplane(Vehicle):    def __init__(self, brand, max_speed, altitude):        super().__init__(brand, max_speed)        self.altitude = altitude        self._wheels = 3    def move(self) -> str:        return f"Літак {self.brand} летить на висоті {self.altitude} м"def task1_demo():    print("=" * 60)    print("ЗАВДАННЯ 1. Ієрархія транспортних засобів")    print("=" * 60)    fleet = [        Car("Toyota", 180, 5),        Bicycle("Giant", 40, 21),        Airplane("Boeing", 900, 10000),    ]    for v in fleet:                          # поліморфний обхід        print(v.move())    print()    print("isinstance(fleet[0], Vehicle):", isinstance(fleet[0], Vehicle))    print("issubclass(Car, Vehicle):     ", issubclass(Car, Vehicle))    print("issubclass(Bicycle, Airplane):", issubclass(Bicycle, Airplane))    print()# ============================================================# ЗАВДАННЯ 2. Інкапсуляція, property та контроль доступу# Предметна область: банківський рахунок# ============================================================class BankAccount:    INTEREST_RATE = 0.05       # атрибут класу    def __init__(self, owner: str, balance: float = 0.0):        self.owner = owner        self._opened_year = 2024            # "захищений" атрибут        self.__balance = 0.0                # "приватний" атрибут        self.balance = balance              # через setter -> валідація    @property    def balance(self) -> float:        return self.__balance    @balance.setter    def balance(self, value: float) -> None:        if not isinstance(value, (int, float)):            raise TypeError(f"Баланс має бути числом, отримано {type(value).__name__}")        if isinstance(value, bool):          # bool — підклас int, відсікаємо            raise TypeError("Баланс не може бути bool")        if value < 0:            raise ValueError(f"Баланс не може бути від'ємним: {value}")        if value > 1_000_000_000:            raise ValueError("Перевищено ліміт рахунку")        self.__balance = float(value)    @property    def yearly_interest(self) -> float:        """Обчислювана read-only властивість."""        return round(self.__balance * self.INTEREST_RATE, 2)    def __str__(self) -> str:        return (f"BankAccount({self.owner}, balance={self.__balance}, "                f"interest={self.yearly_interest})")def task2_demo():    print("=" * 60)    print("ЗАВДАННЯ 2. Інкапсуляція банківського рахунку")    print("=" * 60)    acc = BankAccount("Іван", 1000)    print(acc)    # Валідація: два типи помилок    for bad in (-50, "сто"):        try:            acc.balance = bad        except (ValueError, TypeError) as e:            print(f"Відхилено {bad!r}: {type(e).__name__}: {e}")    # Обчислювана властивість оновлюється автоматично    acc.balance = 2000    print("Відсотки:", acc.yearly_interest)     # 100.0    # Прямий доступ до приватного — AttributeError    try:        print(acc.__balance)    except AttributeError as e:        print("AttributeError:", e)    # Доступ через name mangling    print("Через mangling:", acc._BankAccount__balance)    print()# ============================================================# ЗАВДАННЯ 3. Магічні методи та перевантаження операторів# Сутність: двовимірний вектор# ============================================================class Vector2D:    def __init__(self, x: float, y: float):        self.x = x        self.y = y    # --- Представлення ---    def __str__(self) -> str:        return f"({self.x}; {self.y})"                    # людиночитне    def __repr__(self) -> str:        return f"Vector2D({self.x!r}, {self.y!r})"        # однозначне    # --- Арифметика ---    def __add__(self, other):        if not isinstance(other, Vector2D):            return NotImplemented        return Vector2D(self.x + other.x, self.y + other.y)    def __sub__(self, other):        if not isinstance(other, Vector2D):            return NotImplemented        return Vector2D(self.x - other.x, self.y - other.y)    def __mul__(self, scalar):        if not isinstance(scalar, (int, float)):            return NotImplemented        return Vector2D(self.x * scalar, self.y * scalar)    # --- Порівняння ---    def __eq__(self, other):        if not isinstance(other, Vector2D):            return NotImplemented        return self.x == other.x and self.y == other.y    def __lt__(self, other):        """Порівняння за довжиною."""        if not isinstance(other, Vector2D):            return NotImplemented        return abs(self) < abs(other)    # --- Контейнер / виклик ---    def __abs__(self):        return math.hypot(self.x, self.y)    def __getitem__(self, idx):        if idx == 0:            return self.x        if idx == 1:            return self.y        raise IndexError("Vector2D має лише індекси 0 та 1")    def __len__(self):        return 2    def __call__(self):        """Повертає нормалізований вектор."""        length = abs(self)        if length == 0:            return Vector2D(0, 0)        return Vector2D(self.x / length, self.y / length)def task3_demo():    print("=" * 60)    print("ЗАВДАННЯ 3. Магічні методи Vector2D")    print("=" * 60)    a = Vector2D(3, 4)    b = Vector2D(1, 2)    print("str(a):        ", str(a))    print("repr(a):       ", repr(a))    print("a + b =        ", a + b)    print("a - b =        ", a - b)    print("a * 2 =        ", a * 2)    print("a == Vector2D(3,4):", a == Vector2D(3, 4))    print("a < b:         ", a < b)    print("abs(a) =       ", abs(a))    print("a[0] =         ", a[0], "| len(a) =", len(a))    print("a() =          ", a())         # нормалізований    print()# ============================================================# ЗАВДАННЯ 4. Абстрактні класи та композиція# Предметна область: система обробки платежів# ============================================================# ---------- Компоненти композиції ----------class Logger:    def log(self, msg: str) -> None:        print(f"[LOG] {msg}")class FeeCalculator:    def __init__(self, percent: float):        self.percent = percent    def fee(self, amount: float) -> float:        return round(amount * self.percent / 100, 2)# ---------- Абстрактний базовий клас ----------class PaymentProcessor(ABC):    def __init__(self, logger: Logger, fee_calc: FeeCalculator):        self.logger = logger                    # композиція        self.fee_calc = fee_calc                # композиція    @abstractmethod    def authorize(self, amount: float) -> bool:        ...    @abstractmethod    def capture(self, amount: float) -> str:        ...    @property    @abstractmethod    def provider_name(self) -> str:        ...    # Конкретний метод, доступний усім підкласам    def process(self, amount: float) -> str:        self.logger.log(f"Початок обробки {amount} через {self.provider_name}")        if amount <= 0:            raise ValueError("Сума має бути додатною")        if not self.authorize(amount):            self.logger.log("Авторизація не вдалася")            return "Відхилено"        fee = self.fee_calc.fee(amount)          # делегування компоненту        result = self.capture(amount)        self.logger.log(f"Комісія: {fee}, результат: {result}")        return f"{result} (комісія {fee})"class StripeProcessor(PaymentProcessor):    def authorize(self, amount):        self.logger.log(f"Stripe: авторизація {amount}")        return amount < 10_000    def capture(self, amount):        return f"Stripe: списано {amount}"    @property    def provider_name(self):        return "Stripe"class PayPalProcessor(PaymentProcessor):    def __init__(self, logger, fee_calc, email):        super().__init__(logger, fee_calc)        self.email = email    def authorize(self, amount):        self.logger.log(f"PayPal[{self.email}]: авторизація {amount}")        return amount < 5_000    def capture(self, amount):        return f"PayPal: списано {amount} на {self.email}"    @property    def provider_name(self):        return "PayPal"def task4_demo():    print("=" * 60)    print("ЗАВДАННЯ 4. Абстрактний клас + композиція (платежі)")    print("=" * 60)    logger = Logger()    fee = FeeCalculator(2.5)    try:        PaymentProcessor(logger, fee)        # TypeError    except TypeError as e:        print("TypeError:", e)    processors = [        StripeProcessor(logger, fee),        PayPalProcessor(logger, fee, "user@example.com"),    ]    for p in processors:                      # поліморфізм        print(p.process(1000))        print(p.process(7000))        print("---")    print()# ============================================================# ЗАВДАННЯ 5. Паттерн проектування — Strategy# Предметна область: калькулятор знижок в інтернет-магазині# ============================================================# ---------- Strategy ----------class DiscountStrategy(ABC):    @abstractmethod    def apply(self, amount: float) -> float:        ...    @abstractmethod    def describe(self) -> str:        ...class NoDiscount(DiscountStrategy):    def apply(self, amount):        return amount    def describe(self):        return "Без знижки"class PercentDiscount(DiscountStrategy):    def __init__(self, percent: float):        self.percent = percent    def apply(self, amount):        return round(amount * (1 - self.percent / 100), 2)    def describe(self):        return f"Знижка {self.percent}%"class FixedDiscount(DiscountStrategy):    def __init__(self, value: float):        self.value = value    def apply(self, amount):        return max(0.0, amount - self.value)    def describe(self):        return f"Фіксована знижка {self.value}"# ---------- Розширення: нова стратегія без зміни існуючих класів ----------class SeasonalDiscount(DiscountStrategy):    def __init__(self, percent: float, extra: float):        self.percent = percent        self.extra = extra    def apply(self, amount):        return max(0.0, round(amount * (1 - self.percent / 100) - self.extra, 2))    def describe(self):        return f"Сезонна знижка {self.percent}% + бонус {self.extra}"# ---------- Context ----------class Order:    def __init__(self, items: list, strategy: DiscountStrategy):        self.items = items        self.strategy = strategy    @property    def subtotal(self) -> float:        return sum(self.items)    def total(self) -> float:        return self.strategy.apply(self.subtotal)    def summary(self) -> str:        return (f"Сума: {self.subtotal}, стратегія: {self.strategy.describe()}, "                f"до сплати: {self.total()}")def task5_demo():    print("=" * 60)    print("ЗАВДАННЯ 5. Паттерн Strategy (знижки)")    print("=" * 60)    order = Order([100, 200, 300], NoDiscount())    print(order.summary())    order.strategy = PercentDiscount(10)    print(order.summary())    order.strategy = FixedDiscount(50)    print(order.summary())    order.strategy = SeasonalDiscount(15, 30)   # розширення    print(order.summary())    print()# ============================================================# ТОЧКА ВХОДУ# ============================================================if __name__ == "__main__":    task1_demo()    task2_demo()    task3_demo()    task4_demo()    task5_demo()